// Lê o CSV devolvido pelo HTTP Request.
const raw = $json.data ?? $json.body ?? $json;
const csv = typeof raw === "string" ? raw : String(raw?.data ?? raw?.body ?? "");

if (!csv.trim()) {
  throw new Error("O HTTP Request não devolveu conteúdo CSV.");
}

// Parser CSV simples que respeita campos entre aspas e vírgulas dentro dos campos.
function parseCSVLine(line) {
  const values = [];
  let value = "";
  let quoted = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (quoted && line[i + 1] === '"') {
        value += '"';
        i++;
      } else {
        quoted = !quoted;
      }
    } else if (ch === "," && !quoted) {
      values.push(value.trim());
      value = "";
    } else {
      value += ch;
    }
  }
  values.push(value.trim());
  return values;
}

const lines = csv.replace(/^\uFEFF/, "").split(/\r?\n/).filter(line => line.trim() !== "");
if (lines.length < 2) {
  throw new Error("O CSV não contém linhas de dados.");
}

const headers = parseCSVLine(lines[0]).map(h => h.trim());
const investimentos = lines.slice(1).map(line => {
  const cols = parseCSVLine(line);
  const obj = {};
  headers.forEach((header, i) => obj[header] = cols[i] ?? "");

  // Aceita valores como 1500, R$ 1.500,00 ou 1500.00.
  const rawMinimo = String(obj.minimo ?? "").trim().replace(/[R$\s]/g, "");
  let normalized = rawMinimo;
  if (normalized.includes(",") && normalized.includes(".")) {
    normalized = normalized.replace(/\./g, "").replace(",", ".");
  } else if (normalized.includes(",")) {
    normalized = normalized.replace(",", ".");
  }
  obj.minimo = Number(normalized.replace(/[^\d.-]/g, "")) || 0;
  return obj;
});

return [{ json: { investimentos } }];

// Recolhe os dados do Webhook e a lista de investimentos.
let clientes = [];
let investimentos = [];

for (const item of $input.all()) {
  const j = item.json ?? {};
  const possiveisClientes = j.body?.clientes ?? j.clientes;
  if (Array.isArray(possiveisClientes)) clientes = possiveisClientes;
  if (Array.isArray(j.investimentos)) investimentos = j.investimentos;
}

function parseMoney(value) {
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  let s = String(value ?? "").trim().replace(/[R$\s]/g, "");
  if (s.includes(",") && s.includes(".")) s = s.replace(/\./g, "").replace(",", ".");
  else if (s.includes(",")) s = s.replace(",", ".");
  s = s.replace(/[^\d.-]/g, "");
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

if (!Array.isArray(clientes) || clientes.length === 0) {
  throw new Error('O corpo do Webhook deve incluir uma lista não vazia em "clientes".');
}
if (!Array.isArray(investimentos) || investimentos.length === 0) {
  throw new Error("Não foi possível carregar investimentos do CSV.");
}

const resultados = clientes.map(c => {
  const saldoNum = parseMoney(c.saldo);
  const perfil = String(c.perfil ?? "").trim();
  const doPerfil = investimentos.filter(i =>
    String(i.perfil ?? "").trim().toLowerCase() === perfil.toLowerCase()
  );
  const acessiveis = doPerfil.filter(i => Number(i.minimo) <= saldoNum);

  let escolhido = null;
  let motivo = "";

  if (acessiveis.length > 0) {
    escolhido = [...acessiveis].sort((a, b) => Number(b.minimo) - Number(a.minimo))[0];
    motivo = `Compatível com o perfil ${perfil} e com o saldo informado.`;
  } else if (doPerfil.length > 0) {
    escolhido = [...doPerfil].sort((a, b) => Number(a.minimo) - Number(b.minimo))[0];
    motivo = "O saldo informado é inferior ao mínimo do produto; confirmar elegibilidade antes de qualquer recomendação.";
  }

  const nomeProduto = escolhido?.produto ?? "";
  const rent = escolhido?.rentabilidade ?? "";
  const mensagens = nomeProduto ? [
    `Olá, ${c.nome ?? "cliente"}! Com o seu perfil ${perfil}, temos informação sobre ${nomeProduto} (${rent}).`,
    `${c.nome ?? "Cliente"}, encontrámos uma opção associada ao seu perfil ${perfil}: ${nomeProduto}.`,
    `Olá, ${c.nome ?? "cliente"}! Podemos apresentar-lhe informação sobre ${nomeProduto}, associado ao perfil ${perfil}.`
  ] : [];

  return {
    nome: String(c.nome ?? "").trim(),
    email: String(c.email ?? "").trim(),
    perfil,
    saldo_texto: String(c.saldo ?? ""),
    saldo_num: saldoNum,
    recomendacoes: escolhido,
    motivo: escolhido ? motivo : "Não foi encontrado investimento correspondente ao perfil informado.",
    mensagens,
    mensagem_escolhida: mensagens.length
      ? mensagens[Math.floor(Math.random() * mensagens.length)]
      : "",
    elegivel_para_email: Boolean(escolhido && c.email)
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (typeof valor === "number") return Number.isFinite(valor) ? valor : 0;
  let s = String(valor ?? "").trim().replace(/[R$\s]/g, "");
  if (s.includes(",") && s.includes(".")) s = s.replace(/\./g, "").replace(",", ".");
  else if (s.includes(",")) s = s.replace(",", ".");
  const n = Number(s.replace(/[^\d.-]/g, ""));
  return Number.isFinite(n) ? n : 0;
}

// Mantém todos os clientes para que o fluxo possa tratar também dados incompletos.
// A condição If decide se o e-mail pode ser enviado.
return resultados.map(c => ({
  json: {
    email_to: String(c.email || "").trim(),
    nome: String(c.nome || "cliente").trim(),
    perfil: c.perfil || "não indicado",
    saldo_texto: c.saldo_texto ?? c.saldo ?? "",
    saldo_num: c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo),
    recomendacoes: {
      produto: c.recomendacoes?.produto || "",
      minimo: c.recomendacoes?.minimo ?? "",
      rentabilidade: c.recomendacoes?.rentabilidade || ""
    },
    tem_recomendacao: Boolean(c.recomendacoes?.produto),
    motivo: c.motivo || "Não foi encontrada recomendação para os dados fornecidos.",
    mensagem_base: c.mensagem_escolhida || "",
    copy_rules: {
      idioma: "pt-BR",
      tom: "amigável e profissional",
      tamanho: "curto (4-6 linhas)",
      evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
    }
  }
}));

