const clientes = $("Code in JavaScript2").all();
const out = [];

$input.all().forEach((item, i) => {
  const j = item.json ?? {};
  const base = clientes[i]?.json ?? {};

  const raw =
    j.output?.[0]?.content?.[0]?.text ??
    j.content?.parts?.[0]?.text ??
    j.text ??
    "";

  const limpo = String(raw).replace(/```json|```/gi, "").trim();
  let mail = {};
  try {
    mail = JSON.parse(limpo);
  } catch {
    mail = {};
  }

  const subject = String(mail.subject || "Sugestão de investimento");
  const text_body = String(mail.text_body || base.mensagem_base || "");
  const html_body = String(mail.html_body || `<p>${text_body.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\n/g, "<br>")}</p>`);
  const email = String(base.email_to || "").trim();
  const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  out.push({
    json: {
      ok: Boolean(emailValido && base.tem_recomendacao),
      to: email,
      subject,
      text_body,
      html_body,
      meta: {
        nome: base.nome,
        perfil: base.perfil,
        produto: base.recomendacoes?.produto,
        minimo: base.recomendacoes?.minimo,
        rentabilidade: base.recomendacoes?.rentabilidade,
        motivo: base.motivo
      }
    }
  });
});

return out;
